package com.kholodilin.repogrowth.publicapi;
import com.kholodilin.repogrowth.publication.PublicationService;
import java.time.LocalDate;
import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/public")
public class PublicApiController {
 private final PublicReadService reads;public PublicApiController(PublicReadService reads){this.reads=reads;}
 @GetMapping("/resolve") public Object resolve(@RequestParam String path){var resolved=reads.resolve(path);var answer=new java.util.LinkedHashMap<String,Object>();answer.put("ownerId",Long.toString(resolved.ownerId()));answer.put("repositoryId",resolved.repositoryId()==null?null:resolved.repositoryId().toString());answer.put("canonicalPath",resolved.canonicalPath());answer.put("redirect",resolved.redirect());return answer;}
 @GetMapping("/owners/{owner}/repositories") public Object repositories(@PathVariable String owner,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit,@RequestParam(defaultValue="30d") String period){return reads.repositories(owner,after,limit,period);}
 @GetMapping({"/owners/{owner}/stats","/repositories/{owner}/{repository}/stats"}) public Object stats(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="30d") String period){return reads.stats(owner,repository,period);}
 @GetMapping({"/owners/{owner}/stats-history","/repositories/{owner}/{repository}/stats-history"}) public Object statsHistory(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="30d") String period,@RequestParam(required=false) LocalDate before,@RequestParam(defaultValue="50") int limit){return reads.statsHistory(owner,repository,period,before,limit);}
 @GetMapping({"/owners/{owner}/traffic","/repositories/{owner}/{repository}/traffic"}) public Object traffic(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="30d") String period){return reads.traffic(owner,repository,period);}
 @GetMapping({"/owners/{owner}/traffic-history","/repositories/{owner}/{repository}/traffic-history"}) public Object trafficHistory(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="30d") String period,@RequestParam(required=false) LocalDate before,@RequestParam(defaultValue="50") int limit){return reads.trafficHistory(owner,repository,period,before,limit);}
 @GetMapping({"/owners/{owner}/referrers","/repositories/{owner}/{repository}/referrers"}) public Object referrers(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.sources(owner,repository,false,after,limit);}
 @GetMapping({"/owners/{owner}/paths","/repositories/{owner}/{repository}/paths"}) public Object paths(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.sources(owner,repository,true,after,limit);}
 @GetMapping({"/owners/{owner}/search-queries","/repositories/{owner}/{repository}/search-queries"}) public Object queries(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.definitions(owner,repository,false,after,limit);}
 @GetMapping({"/owners/{owner}/topics","/repositories/{owner}/{repository}/topics"}) public Object topics(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.definitions(owner,repository,true,after,limit);}
 @GetMapping("/search-queries/{id}") public Object searchDefinition(@PathVariable long id){return reads.definition(false,id);}
 @GetMapping("/topic-watches/{id}") public Object topicDefinition(@PathVariable long id){return reads.definition(true,id);}
 @GetMapping("/search-queries/{id}/history") public Object queryHistory(@PathVariable long id,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.rankHistory(false,id,before,limit);}
 @GetMapping("/topic-watches/{id}/history") public Object topicHistory(@PathVariable long id,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.rankHistory(true,id,before,limit);}
 @GetMapping("/search-runs/{id}/results") public Object queryResults(@PathVariable long id,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.rankResults(false,id,after,limit);}
 @GetMapping("/topic-runs/{id}/results") public Object topicResults(@PathVariable long id,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.rankResults(true,id,after,limit);}
 @GetMapping({"/owners/{owner}/growth-events","/repositories/{owner}/{repository}/growth-events"}) public Object events(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.events(owner,repository,before,limit);}
 @GetMapping({"/owners/{owner}/referrer-history","/repositories/{owner}/{repository}/referrer-history"}) public Object referrerHistory(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.sourceHistory(owner,repository,false,before,limit);}
 @GetMapping({"/owners/{owner}/path-history","/repositories/{owner}/{repository}/path-history"}) public Object pathHistory(@PathVariable String owner,@PathVariable(required=false) String repository,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.sourceHistory(owner,repository,true,before,limit);}
 @GetMapping("/search-queries/{id}/series") public Object searchSeries(@PathVariable long id,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.rankSeries(false,id,before,limit);}
 @GetMapping("/topic-watches/{id}/series") public Object topicSeries(@PathVariable long id,@RequestParam(defaultValue="0") long before,@RequestParam(defaultValue="50") int limit){return reads.rankSeries(true,id,before,limit);}
 @GetMapping("/search-queries/{id}/competitors/{githubId}") public Object searchCompetitor(@PathVariable long id,@PathVariable long githubId){return reads.competitor(false,id,githubId);}
 @GetMapping("/topic-watches/{id}/competitors/{githubId}") public Object topicCompetitor(@PathVariable long id,@PathVariable long githubId){return reads.competitor(true,id,githubId);}
 @GetMapping({"/owners/{owner}","/repositories/{owner}/{repository}"}) public Object overview(@PathVariable String owner,@PathVariable(required=false) String repository){return reads.overview(owner,repository);}
 @GetMapping("/search-queries/{id}/results") public Object latestSearch(@PathVariable long id,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.latestResults(false,id,after,limit);}
 @GetMapping("/topic-watches/{id}/results") public Object latestTopic(@PathVariable long id,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.latestResults(true,id,after,limit);}
 @GetMapping("/owners") public Object owners(@RequestParam(defaultValue="stars") String sort,@RequestParam(defaultValue="desc") String order,@RequestParam(defaultValue="0") long after,@RequestParam(defaultValue="50") int limit){return reads.owners(sort,order,after,limit);}
}
